const effect = thisItem.effects.getName("惜余琴");
if (effect) {
    await game.xjzl.api.effects.addEffect(actor, effect.toObject());
}

if (args.actionType !== 'buff') return;
if (args.target.id === actor.id) return; // 假设只对别人生效，根据语境“友方”

let healAmount = 10;

// 简单的异性判断
const selfGender = actor.system.info?.gender || "";
const targetGender = args.target.system.info?.gender || "";

// 如果双方都写了性别且不同
if (selfGender && targetGender && selfGender !== targetGender) {
    healAmount += 20;
}

await args.target.applyHealing({ healer: actor,  amount: healAmount, type: "hp" });

if (!args.isHit) return;
// 添加 'unstable' (下盘不稳) 系统状态
// 这里设置 duration 1 round
const effectData = {
    id: "unstable", // 系统预设ID
    duration: { rounds: 1 }
};
await game.xjzl.api.effects.addEffect(args.target, effectData);

const yanzou = actor.system.arts.yanzou.total || 0;
const jiaoli = actor.system.skills.jiaoli.total || 0;
const extra = yanzou + jiaoli;

args.output.damage += extra;
args.output.bonusDesc.push(`金喇叭(+${extra})`);

if (!args.isCrit) return;

// 自身加士气
const res = actor.system.resources.morale;
const newVal = Math.min(res.max, (res.value || 0) + 10);
await actor.changeResources({ "system.resources.morale.value": newVal }, { cause: "script", source: "move", sourceActor: actor, item: thisItem instanceof Item ? thisItem : (args.item || null), move: typeof move !== "undefined" ? move : (args.move || null) });

ui.notifications.info("沙场号角暴击！自身士气已加，请手动为10米内友方增加10点士气。");

// 查找所有友方
const myToken = actor.token?.object || actor.getActiveTokens()[0];
if (!myToken) return;
const allies = canvas.tokens.placeables.filter(t => t.document.disposition === myToken.document.disposition);

// 乘风是系统状态 (id: chengfeng)
for (const t of allies) {
    if (t.actor) {
        await game.xjzl.api.effects.addEffect(t.actor, "chengfeng");
    }
}
ui.notifications.info("马头琴声起，全军乘风！");

if (args.isCrit) {
    await args.target.applyDamage({
        amount: 10,
        type: "mental",
        attacker: actor,
        isHit: true,
        ignoreDefense: true
    });
    ui.notifications.info("南音琵琶触发：额外10点精神伤害！");
}

if (args.isHit) {
    await args.target.applyDamage({
        amount: 30,
        type: "mental",
        attacker: actor,
        isHit: true,
        ignoreDefense: true
    });
}

// 检测目标是否有“耳鸣”(deaf) 状态
if (args.target.statuses.has("deaf")) {
    // 使用新增加的参数 grantFeint
    // 直接针对该目标，将虚招数值提升 4 点
    args.flags.grantFeint += 4;
}

if (args.isBroken) {
    await game.xjzl.api.effects.addEffect(args.target, "prone"); // 倒地;
}

if ((args.move.type === 'basic' && args.move.id !== 'opportunity-attack')) return;
if (args.isHit) {
    await actor.applyHealing({ healer: actor,  amount: 5, type: "mp" });
}

if (args.isHit) {
    const effectData = { id: "unstable", duration: { rounds: 2 } };
    await game.xjzl.api.effects.addEffect(args.target, effectData);
}

// 1. 基础命中与目标检查
if (!args.isHit || !args.target) return;

// 2. 排除架招和气招 (仅实招/虚招/反击/普攻生效)
if (["stance", "qi"].includes(args.move.type)) return;

// 3. 执行流失伤害
// type: "liushi" + ignoreDefense: true 确保无视防御直接扣血
await args.target.applyDamage({
    amount: 20,
    type: "liushi",
    attacker: actor,
    isHit: true,
    ignoreDefense: true
});

// 4. 手动发送提示卡片 (弥补 applyDamage 不会为传参伤害发流失卡的机制)
ChatMessage.create({
    content: `<div class="xjzl-chat-card">
        <div class="card-content" style="color:#8b0000; font-weight:bold; padding:4px; border-left: 3px solid #8b0000; background: rgba(139, 0, 0, 0.05); font-size: 0.9em;">
            <i class="fas fa-tint"></i> 破釜沉舟：额外造成 20 点气血流失
        </div>
    </div>`,
